CREATE POLICY personnel_voice_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'voice-messages' AND (storage.foldername(name))[1] = auth.uid()::text AND public.is_personnel());
CREATE POLICY own_voice_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'voice-messages' AND (storage.foldername(name))[1] = auth.uid()::text AND public.is_personnel());